<template>
	<view class="order-page">
		<MobileHeader :title="pageTitle" :back="screen !== 'orders'" @back="goBack" />

		<scroll-view scroll-y class="page-scroll">
			<template v-if="screen === 'confirm'">
				<view class="address-card card" @click="open('address')">
					<view class="pin"><AppIcon name="pin" size="29rpx" tone="light"/></view>
					<view class="address-main"><view><text class="name">{{account.name || '收货人'}}</text><text class="phone">{{maskedPhone}}</text></view><text class="address">{{account.address || '请填写收货地址'}}</text><text class="hint">{{account.stationName ? `由 ${account.stationName} 配送` : '点击设置收货地址'}}</text></view><text class="chevron">›</text>
				</view>
				<view class="line-row card" @click="chooseWindow"><text>配送时间</text><text class="row-value">{{deliveryWindow}}　›</text></view>
				<view class="card goods-card">
					<text class="section-title">商品清单</text>
					<view class="goods-line"><WaterJug size="small"/><view class="goods-copy"><text class="goods-name">{{checkoutItem.name}}</text><text class="muted">{{checkoutItem.spec}}</text></view><view class="goods-price"><text>¥{{formatAmount(checkoutItem.price)}}</text><text class="muted">×{{checkoutItem.qty}}</text></view></view>
					<view class="discount-row" @click="chooseCoupon"><view><AppIcon name="coupon" size="28rpx"/><text>优惠券</text></view><text :class="{'ui-strong':selectedCoupon}">{{ couponLabel }}</text></view>
					<view v-if="couponDiscountCents>0" class="discount-row"><view><text>已优惠</text></view><text class="ui-strong minus">-¥{{ formatAmount(couponDiscountCents/100) }}</text></view>
					<view class="discount-row"><view><AppIcon name="ticket" size="28rpx"/><text>电子水票</text></view><text>抵扣规则待配置</text></view>
				</view>
				<view class="line-row card"><text>订单备注</text><input v-model="remark" class="remark-input" placeholder="请填写备注信息（选填）" /></view>
				<view class="card"><text class="section-title">支付方式</text><PayOptions v-model="payMethod" :compact="true" /></view>
			</template>

			<template v-else-if="screen === 'checkout'">
				<view class="amount-card card"><text>应付金额</text><text class="big-amount"><text>¥</text>{{checkoutTotal}}</text><text class="pay-countdown">请确认支付方式后完成订单</text></view>
				<view class="card pay-card"><text class="section-title">支付方式</text><PayOptions v-model="payMethod" /></view>
				<view class="safe-note">♢　清泉到家 · 支付安全保障中</view>
			</template>

			<template v-else-if="screen === 'success'">
				<view class="success-panel">
					<view class="success-icon">✓</view><text class="success-title">支付成功</text><text class="muted">订单已提交，感谢您的信任！</text>
					<view class="delivery-window"><text>预计送达时间</text><text class="ui-strong">{{currentOrder?.deliveryWindow || '按水站排单尽快送达'}}</text><text>我们将准时为您送达，请保持电话畅通</text></view>
					<view class="success-detail"><view><text>订单编号</text><text>{{currentOrder?.id || '正在生成'}}</text></view><view><text>下单时间</text><text>{{formatDateTime(currentOrder?.createdAt)}}</text></view><view><text>支付方式</text><text>{{currentOrder?.payment || '微信支付'}}</text></view><view v-if="Number(currentOrder?.discount||0)>0"><text>优惠券抵扣</text><text class="minus">-¥{{formatAmount(currentOrder?.discount)}}</text></view><view><text>实付金额</text><text class="minus">¥{{formatAmount(currentOrder?.amount)}}</text></view></view>
					<view class="notify-card"><view class="notify-icon"><AppIcon name="bell" size="31rpx"/></view><view><text>配送进度会实时同步到「我的订单」</text><text class="ui-small">微信订阅消息需在小程序端配置模板后开启</text></view><button @click="open('orders')">查看进度</button></view>
				</view>
			</template>

			<template v-else-if="screen === 'orders'">
				<view class="search-box"><AppIcon name="search" size="27rpx" tone="muted"/><input v-model="orderKeyword" class="search-input" placeholder="搜索订单号/商品" confirm-type="search" /><text v-if="orderKeyword" class="search-clear" @click="orderKeyword=''">×</text></view>
				<view class="status-tabs"><text v-for="tab in tabs" :key="tab" :class="{active: activeTab===tab}" @click="activeTab=tab">{{tab}}</text></view>
				<view class="order-card card" v-for="item in visibleOrders" :key="item.no" @click="selectOrder(item)">
					<view class="order-head"><text>订单号：{{item.no}}</text><text :class="item.color">{{item.status}}</text></view>
					<view class="goods-line"><WaterJug size="small"/><view class="goods-copy"><text class="goods-name">{{item.product || '桶装水'}}</text><text class="muted">{{item.spec || `× ${item.qty}`}}</text></view><text class="order-price">¥{{item.amount}}</text></view>
					<view class="order-foot"><text>下单时间：{{item.time}}</text><view><button v-if="item.status==='配送中'" disabled>配送中</button><button v-else @click.stop="rebuy(item)">再次购买</button></view></view>
				</view>
				<view v-if="!visibleOrders.length" class="empty-orders"><AppIcon name="order" size="72rpx" tone="muted"/><text class="ui-strong">{{orderKeyword ? '没有匹配的订单' : '暂无订单'}}</text><text class="ui-small">{{orderKeyword ? '换个关键词试试' : '去首页挑一桶好水吧'}}</text></view>
			</template>

			<template v-else-if="screen === 'detail'">
				<view class="detail-hero"><view><text class="detail-state">{{selectedOrder?.status || '待配送'}}</text><text>{{orderStatusNote}}</text></view><view class="scooter"><AppIcon name="truck" size="72rpx" tone="light"/></view></view>
				<view class="courier card"><view class="avatar">{{(selectedOrder?.courierName || '待').slice(0,1)}}</view><view><text class="name">{{selectedOrder?.courierName || '等待后台派单'}}</text><text class="muted">{{selectedOrder?.dispatchStatus || '待派单'}}{{selectedOrder?.courierPhone ? ` · ${selectedOrder.courierPhone}` : ''}}</text></view><button :class="{disabled:!selectedOrder?.courierPhone}" @click="callCourier"><AppIcon name="phone" size="30rpx" tone="light"/></button></view>
				<view class="card detail-address"><view class="detail-contact"><AppIcon name="pin" size="27rpx"/><text>{{selectedOrder?.customer || '客户'}}　{{selectedOrder?.phone || ''}}</text></view><text class="ui-strong">{{selectedOrder?.address || '地址待同步'}}</text><text class="ui-small">{{selectedOrder?.station || '清泉水站'}}</text></view>
				<view class="card"><text class="section-title">商品清单</text><view class="goods-line"><WaterJug size="small"/><view class="goods-copy"><text class="goods-name">{{selectedOrder?.product || '清泉天然饮用水'}}</text><text class="muted">{{selectedOrder?.spec || '18.9L/桶'}}</text></view><text>×{{selectedOrder?.quantity || selectedOrder?.qty || 1}}　¥{{formatAmount(selectedOrder?.amount)}}</text></view><view class="summary"><text>商品金额</text><text>¥{{formatAmount(Number(selectedOrder?.amount||0)+Number(selectedOrder?.discount||0))}}</text><template v-if="Number(selectedOrder?.discount||0)>0"><text>优惠券</text><text class="minus">-¥{{formatAmount(selectedOrder?.discount)}}</text></template><text>配送费</text><text>¥0.00</text><text class="ui-strong">实付金额</text><text class="ui-strong minus">¥{{formatAmount(selectedOrder?.amount)}}</text></view></view>
				<view class="card order-info"><view><text>订单编号</text><text @click="copyOrderId">{{selectedOrder?.id || selectedOrder?.no}}　<text class="copy-link">复制</text></text></view><view><text>下单时间</text><text>{{formatDateTime(selectedOrder?.createdAt)}}</text></view><view v-if="selectedOrder?.deliveryWindow"><text>配送时段</text><text>{{selectedOrder.deliveryWindow}}</text></view><view><text>支付方式</text><text>{{selectedOrder?.payment || '微信支付'}}</text></view><view v-if="selectedOrder?.remark"><text>订单备注</text><text>{{selectedOrder.remark}}</text></view><view v-if="selectedOrder?.refundStatus && selectedOrder.refundStatus!=='未退款'"><text>退款状态</text><text>{{selectedOrder.refundStatus}} · ¥{{formatAmount(selectedOrder.refundedAmount)}}</text></view><view v-if="selectedOrder?.completedAt"><text>签收时间</text><text>{{formatDateTime(selectedOrder.completedAt)}}{{selectedOrder.signMethod==='ticket' ? ' · 水票核销' : ''}}</text></view></view>
				<view v-if="selectedOrder?.proofUrl" class="card proof-card"><text class="section-title">送达凭证</text><image class="proof-image" :src="fileUrl(selectedOrder.proofUrl)" mode="aspectFill" @click="previewImage(fileUrl(selectedOrder.proofUrl))"/></view>
			</template>

			<template v-else-if="screen === 'refund'">
				<view class="card refund-goods"><WaterJug size="small"/><view><text class="goods-name">{{selectedOrder?.product || '清泉天然饮用水'}}</text><text class="muted">{{selectedOrder?.spec || '18.9L/桶'}}</text><text class="muted">订单编号　{{selectedOrder?.id || selectedOrder?.no}}</text></view><text>¥{{formatAmount(selectedOrder?.amount)}}</text></view>
				<view class="card refund-card"><text class="section-title">售后类型</text><view class="radio-line" @click="refundType='refund'"><text :class="{selected: refundType==='refund'}">●</text><view><text class="ui-strong">仅退款</text><text class="ui-small">未收到商品或不需要退货</text></view></view><view class="radio-line" @click="refundType='return'"><text :class="{selected: refundType==='return'}">●</text><view><text class="ui-strong">退货退款</text><text class="ui-small">已收到商品，需要退货</text></view></view></view>
				<view class="card"><text class="section-title">退款原因</text><view class="reason-tags"><text v-for="reason in reasons" :key="reason" :class="{active: refundReason===reason}" @click="refundReason=reason">{{reason}}</text></view><view class="refund-amount"><text>申请金额</text><text class="ui-strong">¥{{formatAmount(selectedOrder?.amount)}}</text></view></view>
				<view class="card"><text class="section-title">问题描述</text><textarea v-model="refundDesc" maxlength="200" placeholder="请详细描述您遇到的问题，便于我们尽快处理"/><view class="upload-row"><view v-for="(path,index) in refundImages" :key="path" class="upload-thumb"><image :src="path" mode="aspectFill"/><text class="remove" @click.stop="refundImages.splice(index,1)">×</text></view><view v-if="refundImages.length<3" class="upload" @click="chooseRefundImages">＋<text class="ui-small">上传凭证</text></view></view><text class="ui-small">最多 3 张，仅支持 JPG/PNG/WebP，单张不超过 2MB</text></view>
			</template>
			<template v-if="screen === 'address'">
				<view class="card address-form"><text class="section-title">收货信息</text><view class="form-line"><text>收货人</text><input v-model="addressForm.name" maxlength="20" placeholder="请输入收货人姓名" /></view><view class="form-line"><text>手机号</text><text class="muted">{{account.phone || '--'}}（如需修改请联系水站）</text></view><view class="form-line"><text>所属水站</text><text class="muted">{{account.stationName || '由水站分配'}}</text></view><view class="form-line column"><text>详细地址</text><textarea v-model="addressForm.address" maxlength="120" placeholder="小区、楼栋、单元、门牌号" /></view></view>
				<text class="ui-small address-tip">地址保存后会作为后续所有订单的默认收货地址</text>
			</template>
		</scroll-view>

		<view v-if="screen==='confirm'" class="bottom-action"><view>合计：<text class="ui-strong">¥{{checkoutTotal}}</text></view><button @click="open('checkout')">提交订单</button></view>
		<view v-else-if="screen==='checkout'" class="single-action"><button :disabled="submitting" @click="submitPayment">{{submitting ? '正在同步订单…' : `确认支付 ¥${checkoutTotal}`}}</button></view>
		<view v-else-if="screen==='success'" class="double-action"><button class="ghost" @click="goShop">返回首页</button><button @click="open('orders')">查看订单</button></view>
		<view v-else-if="screen==='detail'" class="double-action"><button v-if="canCancelOrder" class="ghost" :disabled="submitting" @click="cancelSelectedOrder">取消订单</button><button v-else class="ghost" disabled>客服 400-888-1998</button><button v-if="selectedOrder?.payStatus==='已支付' && selectedOrder?.status!=='已取消'" @click="open('refund')">申请售后</button><button v-else disabled>订单处理中</button></view>
		<view v-else-if="screen==='refund'" class="single-action"><button :disabled="submitting" @click="submitRefund">{{submitting ? '正在提交…' : '提交申请'}}</button></view>
		<view v-else-if="screen==='address'" class="single-action"><button :disabled="submitting" @click="saveAddress">{{submitting ? '保存中…' : '保存地址'}}</button></view>
	</view>
</template>

<script>
import MobileHeader from '../../components/MobileHeader.vue'
import WaterJug from '../../components/WaterJug.vue'
import PayOptions from '../../components/PayOptions.vue'
import AppIcon from '../../components/AppIcon.vue'
import { waterApi } from '../../services/waterApi.js'

export default {
	components: { MobileHeader, WaterJug, PayOptions, AppIcon },
	data() {
		return {
			screen: 'confirm', remark: '', payMethod: 'wechat', activeTab: '全部', refundType: 'refund', refundReason: '商品破损', refundDesc: '', checkoutItem:{sku:'water-18_9l',name:'清泉天然饮用水',spec:'18.9L 桶装水',price:29.95,qty:1,station:'中央站'},
			tabs: ['全部','待付款','待配送','配送中','已完成','已取消'], reasons: ['商品破损','商品错发','商品质量问题','其他原因'],
			currentOrder: null, selectedOrder: null, submitting: false, refreshTimer: null, paymentRequestId: '',
			coupons: [], selectedCouponId: '', account: { name: '', phone: '', address: '', stationName: '' }, addressForm: { name: '', address: '' }, returnScreen: 'confirm',
			deliveryWindow: '今天 10:00–11:00', deliveryWindows: [], orderKeyword: '', refundImages: [],
			orders: [
				{id:'QD20250517000123',no:'QD20250517000123',status:'配送中',color:'green',product:'清泉天然饮用水',spec:'18.9L 桶装水 × 2',qty:2,amount:'59.90',time:'2025-05-17 09:45'},
				{id:'QD20250515000456',no:'QD20250515000456',status:'已完成',color:'mint',product:'清泉天然饮用水',spec:'18.9L 桶装水 × 1',qty:1,amount:'29.95',time:'2025-05-15 11:20'},
				{id:'QD20250512000378',no:'QD20250512000378',status:'已完成',color:'mint',product:'清泉天然饮用水',spec:'18.9L 桶装水 × 3',qty:3,amount:'89.85',time:'2025-05-12 16:30'}
			]
		}
	},
	computed: {
		pageTitle(){ return {confirm:'确认订单',checkout:'收银台',success:'支付成功',orders:'我的订单',detail:'订单详情',refund:'申请售后',address:'收货地址'}[this.screen] },
		visibleOrders(){ const keyword=this.orderKeyword.trim(); return this.orders.filter(i=>(this.activeTab==='全部'||i.status===this.activeTab)&&(!keyword||`${i.id}${i.product||''}${i.spec||''}`.includes(keyword))) },
		maskedPhone(){ const value=String(this.account.phone||''); return value.length===11?`${value.slice(0,3)} ${value.slice(3,7)} ${value.slice(7)}`:value },
		orderStatusNote(){ return {'待付款':'请尽快完成支付','待配送':'订单已支付，正在等待水站派单','配送中':'师傅正在为您配送，请耐心等待','已完成':'订单已完成，感谢您的信任','已取消':'订单已取消，库存占用已释放'}[this.selectedOrder?.status] || '订单状态正在同步' },
		grossCents(){return Math.round(Number(this.checkoutItem.price||0)*100)*Number(this.checkoutItem.qty||1)},
		applicableCoupons(){return this.coupons.filter(c=>c.customerCouponId&&c.customerStatus==='未使用'&&c.status==='启用'&&(c.type!=='满减券'||this.grossCents>=Math.round(Number(c.minimum||0)*100)))},
		selectedCoupon(){return this.applicableCoupons.find(c=>c.customerCouponId===this.selectedCouponId)||null},
		couponDiscountCents(){if(!this.selectedCoupon)return 0;return Math.max(0,Math.min(Math.round(Number(this.selectedCoupon.discount||0)*100),this.grossCents-1))},
		couponLabel(){if(this.selectedCoupon)return `${this.selectedCoupon.name} -¥${(this.couponDiscountCents/100).toFixed(2)}`;return this.applicableCoupons.length?`${this.applicableCoupons.length} 张可用 ›`:'暂无可用优惠券'},
		checkoutTotal(){return Math.max(0.01,(this.grossCents-this.couponDiscountCents)/100).toFixed(2)},
		canCancelOrder(){return this.selectedOrder?.status==='待付款'||(this.selectedOrder?.status==='待配送'&&this.selectedOrder?.payment==='余额支付')}
	},
	onLoad(query){ const saved=uni.getStorageSync('mountain-spring-checkout');if(saved?.sku)this.checkoutItem=saved;if(query && query.screen) this.screen=query.screen; if(query && query.tab && this.tabs.includes(query.tab)) this.activeTab=query.tab; this.buildDeliveryWindows(); this.loadAccount(); if(['confirm','checkout'].includes(this.screen)) this.loadCoupons(); if(['orders','detail'].includes(this.screen)) this.startSync(); if(this.screen==='address') this.returnScreen='orders' },
	onShow(){ if(['orders','detail'].includes(this.screen)) this.startSync() },
	onUnload(){ this.stopSync() },
	methods: {
		open(name){ if(name==='address'){ this.returnScreen=this.screen; this.addressForm={name:this.account.name||'',address:this.account.address||''} } this.screen=name; uni.pageScrollTo({scrollTop:0,duration:0}); if(['orders','detail'].includes(name)) this.startSync(); else this.stopSync() },
		goBack(){ if(this.screen==='confirm'||this.screen==='orders') uni.navigateBack(); else if(this.screen==='address') this.open(this.returnScreen==='address'?'orders':this.returnScreen); else this.open({checkout:'confirm',success:'checkout',detail:'orders',refund:'detail'}[this.screen]||'orders') },
		fileUrl(path){ return waterApi.fileUrl(path) },
		previewImage(url){ if(typeof uni.previewImage==='function') uni.previewImage({urls:[url]}) },
		buildDeliveryWindows(){ const slots=['10:00–11:00','14:00–15:00','16:00–17:00']; const hour=new Date().getHours(); const today=slots.filter(slot=>Number(slot.slice(0,2))>hour+1).map(slot=>`今天 ${slot}`); const tomorrow=['09:00–10:00',...slots].map(slot=>`明天 ${slot}`); this.deliveryWindows=[...today,...tomorrow]; this.deliveryWindow=this.deliveryWindows[0] },
		chooseWindow(){ uni.showActionSheet({itemList:this.deliveryWindows,success:res=>{ this.deliveryWindow=this.deliveryWindows[res.tapIndex] }}) },
		async loadAccount(){ try{ this.account=await waterApi.getAccount(); if(this.screen==='address'&&!this.addressForm.name&&!this.addressForm.address) this.addressForm={name:this.account.name||'',address:this.account.address||''} }catch(error){ console.warn('[account-sync]',error.message) } },
		async saveAddress(){ if(this.submitting)return; const name=this.addressForm.name.trim(); const address=this.addressForm.address.trim(); if(!name)return this.toast('请填写收货人'); if(address.length<4)return this.toast('请填写详细收货地址'); this.submitting=true; try{ this.account=await waterApi.updateAccount({name,address}); this.toast('收货地址已保存'); setTimeout(()=>this.goBack(),500) }catch(error){ this.toast(error.message) }finally{ this.submitting=false } },
		rebuy(item){ const qty=Number(item.quantity||item.qty||1); const price=(Number(item.amount||0)+Number(item.discount||0))/qty; this.checkoutItem={sku:item.skuCode||this.checkoutItem.sku,name:item.product||this.checkoutItem.name,spec:String(item.spec||'').replace(/ × \d+$/,''),price:Number(price.toFixed(2)),qty,station:item.station||'中央站'}; uni.setStorageSync('mountain-spring-checkout',this.checkoutItem); this.selectedCouponId=''; this.loadCoupons(); this.open('confirm') },
		copyOrderId(){ const id=this.selectedOrder?.id||this.selectedOrder?.no; if(!id)return; uni.setClipboardData({data:String(id),success:()=>this.toast('订单号已复制')}) },
		callCourier(){ const phone=String(this.selectedOrder?.courierPhone||'').replace(/\D/g,''); if(phone.length!==11)return this.toast('派单后可联系送水员'); if(typeof uni.makePhoneCall!=='function')return this.toast(`送水员电话 ${phone}`); uni.makePhoneCall({phoneNumber:phone,fail:error=>{ if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('拨号失败') }}) },
		chooseRefundImages(){ if(typeof uni.chooseImage!=='function')return this.toast('当前环境不支持选择图片'); uni.chooseImage({count:3-this.refundImages.length,sizeType:['compressed'],success:result=>{ this.refundImages=[...this.refundImages,...(result.tempFilePaths||[])].slice(0,3) },fail:error=>{ if(!/cancel/i.test(String(error&&error.errMsg)))this.toast('选择图片失败') }}) },
		goShop(){ uni.reLaunch({url:'/pages/index/index'}) },
		toast(title){ uni.showToast({title,icon:'none'}) },
		formatAmount(value){ return Number(value || 0).toFixed(2) },
		formatDateTime(value){ if(!value)return '刚刚'; const date=new Date(value); return Number.isNaN(date.getTime())?'刚刚':`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')} ${String(date.getHours()).padStart(2,'0')}:${String(date.getMinutes()).padStart(2,'0')}` },
		mapOrder(order){ return {...order,no:order.id,qty:order.quantity,amount:this.formatAmount(order.amount),time:this.formatDateTime(order.createdAt),color:order.status==='配送中'?'green':order.status==='已完成'?'mint':''} },
		async loadOrders(){ try{const data=await waterApi.listOrders();this.orders=data.map(order=>this.mapOrder(order));if(this.selectedOrder){const latest=this.orders.find(item=>item.id===this.selectedOrder.id);if(latest)this.selectedOrder=latest}}catch(error){console.warn('[order-sync]',error.message)} },
		startSync(){ this.stopSync();this.loadOrders();this.refreshTimer=setInterval(()=>this.loadOrders(),4000) },
		stopSync(){ if(this.refreshTimer){clearInterval(this.refreshTimer);this.refreshTimer=null} },
		selectOrder(item){ this.selectedOrder=item;this.open('detail') },
		async loadCoupons(){ try{ this.coupons=await waterApi.listCoupons() }catch(error){ console.warn('[coupon-sync]',error.message) } },
		chooseCoupon(){ const options=this.applicableCoupons; if(!options.length)return this.toast('暂无可用优惠券'); const items=options.map(c=>`${c.name}（-¥${Number(c.discount).toFixed(2)}）`); items.push('不使用优惠券'); uni.showActionSheet({itemList:items,success:res=>{ if(res.tapIndex>=options.length){this.selectedCouponId=''}else{this.selectedCouponId=options[res.tapIndex].customerCouponId} }}) },
		async submitPayment(){ if(this.submitting)return;this.submitting=true;if(!this.paymentRequestId)this.paymentRequestId=`checkout-${Date.now()}-${Math.random().toString(36).slice(2,10)}`;try{const paymentNames={wechat:'微信支付',balance:'余额支付',cod:'货到付款'};if(this.payMethod==='ticket')throw new Error('水票抵扣规则尚未配置');if(this.payMethod==='cod')throw new Error('货到付款状态流程尚未配置');const payment=paymentNames[this.payMethod]||'微信支付';if(!this.account.address)throw new Error('请先设置收货地址');const created=await waterApi.createOrder({idempotencyKey:this.paymentRequestId,sku:this.checkoutItem.sku,address:this.account.address,station:this.checkoutItem.station||this.account.stationName||'中央站',quantity:Number(this.checkoutItem.qty||1),payment,remark:this.remark,deliveryWindow:this.deliveryWindow,customerCouponId:this.selectedCouponId||undefined});this.currentOrder=await waterApi.payOrder(created.id,{payment});this.selectedOrder=this.mapOrder(this.currentOrder);this.paymentRequestId='';this.selectedCouponId='';uni.removeStorageSync('mountain-spring-checkout');this.open('success')}catch(error){this.toast(error.message)}finally{this.submitting=false} },
		async submitRefund(){if(!this.selectedOrder?.id)return this.toast('请先选择订单');if(this.submitting)return;this.submitting=true;try{const attachments=[];for(const path of this.refundImages){const uploaded=await waterApi.uploadImage(path);attachments.push(uploaded.url)}await waterApi.createAftersale({orderId:this.selectedOrder.id,type:this.refundType==='return'?'退货退款':'仅退款',reason:`${this.refundReason}${this.refundDesc?`：${this.refundDesc}`:''}`,amount:Number(this.selectedOrder.amount||0),returnQuantity:this.refundType==='return'?Number(this.selectedOrder.quantity||1):0,attachments});this.refundImages=[];this.refundDesc='';this.toast('售后申请已提交');setTimeout(()=>this.open('orders'),600)}catch(error){this.toast(error.message)}finally{this.submitting=false}},
		async cancelSelectedOrder(){if(!this.selectedOrder?.id||this.submitting)return;this.submitting=true;try{const cancelled=await waterApi.cancelOrder(this.selectedOrder.id);this.selectedOrder=this.mapOrder(cancelled);await this.loadOrders();this.toast(cancelled.refundStatus==='已退款'?'订单已取消，余额已退回':'订单已取消')}catch(error){this.toast(error.message)}finally{this.submitting=false}}
	}
}
</script>

